for i,((ids,arg),start) in enumerate(zip(new_specs,starts)):
    end=starts[i+1]-1 if i+1<len(starts) else line_count
    new_rows.append(record(addition,start,end,ids,arg,'mathematical/source incorporation reviewed; final binding separate'))
assert [i for r in new_rows for i in range(r['start_line'],r['end_line']+1)]==list(range(1,line_count+1))
r6=ROOT/'work/quartic-optimization-20261107/resume-release-inventory-20261107-r6/APPLICATION-DELTA.json'
(H/'V14-COVERAGE.json').write_text(json.dumps({'reviewer':'/root/astra_v14_source_review',
    'coverage':new_rows,'r6_inventory_sha256':sha(r6.read_bytes()),
    'reconciliation_scope':'Every new substantive use found in INITIAL-SOURCE-USES has a mapped R6 record. Superseded alternatives and intermediate-only arithmetic are not final proof premises. N48 is recorded under its316 family entry but its covered candidates include the selected314 lift.',
    'initial_record_sha256':sha((H/'INITIAL-SOURCE-USES.md').read_bytes())},indent=2)+'\n')
print(json.dumps({'baseline_ranges':len(rows),'baseline_lines':sum(r['end_line']-r['start_line']+1 for r in rows),'application_ids':len({x for r in rows for x in r['matched_inventory_ids']}),'addition_ranges':len(new_rows),'addition_lines':line_count,'addition_sha256':data['current_addition_sha256']},indent=2))
